manufacturer = value['Manufacturer'].iloc[0].upper() if 'Manufacturer' in value.columns else ''

# Check InPlanePhaseEncodingDirection first (should be COL for A-P axis)
if 'InPlanePhaseEncodingDirection' in value.columns:
    pe_dir = str(value['InPlanePhaseEncodingDirection'].iloc[0]).upper()
    if pe_dir != 'COL':
        raise ValidationError(f"DWI phase encoding should be along COL (A-P axis). Found: {pe_dir}")

# Vendor-specific polarity checks
if 'SIEMENS' in manufacturer:
    if 'PhaseEncodingDirectionPositive' in value.columns:
        pe_positive = value['PhaseEncodingDirectionPositive'].iloc[0]
        if pe_positive is not None:
            pe_positive = int(pe_positive)
            if pe_positive != 0:
                raise ValidationError(f"Siemens DWI should use P-A phase encoding (PhaseEncodingDirectionPositive=0). Found: {pe_positive}")
    else:
        raise ValidationWarning("Siemens PhaseEncodingDirectionPositive not found. Cannot verify P-A phase encoding polarity.")

elif 'GE' in manufacturer:
    if 'RectilinearPhaseEncodeReordering' in value.columns:
        pe_reorder = str(value['RectilinearPhaseEncodeReordering'].iloc[0]).upper()
        # REVERSE_LINEAR indicates reversed phase encoding direction
        if 'REVERSE' not in pe_reorder:
            raise ValidationWarning(f"GE DWI typically uses REVERSE_LINEAR for P-A encoding. Found: {pe_reorder}")
    else:
        raise ValidationWarning("GE RectilinearPhaseEncodeReordering not found. Cannot verify phase encoding polarity.")

elif 'PHILIPS' in manufacturer:
    raise ValidationWarning("Philips DICOM does not encode phase encoding polarity. Please manually verify P-A phase encoding direction.")
